<script>
 import {onMount,tick} from 'svelte';
 import {excelWindow,excelCapabilities,EXCEL_TABS,excelDefaultFormat} from './excel-state.js';
 import {excelSelectionRange,excelVisibleRows} from './excel-model.js';
 import {evaluateWorkbook,parseCellReference,parseRange,columnName,formatCellValue,chartData} from './office-spreadsheet-kernel.js';
 import {createMicrosoftOfficeNativeView} from './microsoft-office-native.js';
 import './microsoft-office.css';
 import './excel.css';
 import {createDocumentFonts} from './document-fonts.svelte.js';
 let {state:excelState,profile,windowId,window=null,execute,registerView=()=>{},available=true,active=true,controls={},getShared=name=>controls.getShared?.(name),getFile=id=>controls.getFile?.(id)}=$props();
 let root=$state(),focusedCell=$state(null),operationError=$state(''),dialogDraft=$state(''),rangeDraft=$state('A1:D6'),columnDraft=$state(1),chartType=$state('bar'),formatDraft=$state('General'),sortDescending=$state(false),sortHeader=$state(true),pasteDraft=$state(''),lastDialog=$state(null);
 const w=$derived(excelWindow(excelState,windowId));
 const cap=$derived(excelCapabilities(profile));
 const sheet=$derived(w?.document.sheets.find(s=>s.id===w.document.activeSheetId));
 const computed=$derived(w?evaluateWorkbook(w.document):{sheets:{},dependencies:{}});
 const selection=$derived(w?excelSelectionRange(w):'A1');
 const selected=$derived(parseCellReference(w?.selection.focus??'A1'));
 const selectedCell=$derived(sheet?.cells[w?.selection.focus]);
 const selectedFormat=$derived(selectedCell?.format??excelDefaultFormat());
 const selectionBounds=$derived(parseRange(selection));
 const startRow=$derived(Math.max(1,selected.row-15));
 const rows=$derived(w?[...new Set([...excelVisibleRows(w,1,w.view.frozenRows,computed),...excelVisibleRows(w,startRow,Math.min(1048576,startRow+69),computed)])]:[]);
 const startColumn=$derived(Math.max(1,selected.column-8));
 const columns=$derived(Array.from({length:Math.min(16,16385-startColumn)},(_,i)=>startColumn+i));
 const charts=$derived(sheet?.charts.map(chart=>({...chart,data:chartData(w.document,sheet.id,chart.range,computed)}))??[]);
 const selectedChart=$derived(sheet?.charts.find(c=>c.id===w?.selectedChartId));
 const stats=$derived(selectionBounds.addresses.map(a=>computed.sheets[sheet?.id]?.[a]).filter(v=>v?.type==='number').map(v=>v.value));
 $effect(()=>{if(w?.dialog!==lastDialog){lastDialog=w?.dialog;dialogDraft=w?.dialog==='rename-sheet'?sheet?.name??'':w?.dialog==='save-as'?w?.document.title+'.xlsx':w?.findQuery??'';rangeDraft=selection;columnDraft=selectionBounds.minColumn;formatDraft=selectedFormat.numberFormat;}});
 async function send(suffix,payload={}){const result=await execute('excel.'+suffix,{windowId},payload);operationError=result?.status==='rejected'?result.error?.message??'Operation rejected.':'';return result;}
 const format=patch=>send('range.format',{range:selection,format:patch});
 function inSelection(row,column){return row>=selectionBounds.minRow&&row<=selectionBounds.maxRow&&column>=selectionBounds.minColumn&&column<=selectionBounds.maxColumn;}
 async function selectCell(address,extend=false){await send('selection.set',{range:extend?w.selection.anchor+':'+address:address});}
 async function navigate(event,address){
  const at=parseCellReference(address);
  if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();await send('save');return;}
  if(event.key==='Escape'){event.target.value=sheet.cells[address]?.input??'';event.target.blur();return;}
  const arrows={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]};
  const isArrow=Object.hasOwn(arrows,event.key);
  if(isArrow&&event.target.value!==(sheet.cells[address]?.input??''))return;
  const delta=isArrow?arrows[event.key]:({Enter:[event.shiftKey?-1:1,0],Tab:[0,event.shiftKey?-1:1]})[event.key];
  if(!delta)return;
  event.preventDefault();
  if(event.target.value!==(sheet.cells[address]?.input??'')){const saved=await send('cell.set',{address,input:event.target.value});if(saved?.status!=='applied')return;}
  const [r,c]=delta,next=columnName(Math.max(1,Math.min(16384,at.column+c)))+Math.max(1,Math.min(1048576,at.row+r));
  await selectCell(next,isArrow&&event.shiftKey);await tick();root.querySelector('[data-office-control="cell-'+next+'"]')?.focus();
 }
 function piePath(values,index){const total=values.reduce((a,b)=>a+Math.max(0,b),0);if(!total)return '';const start=values.slice(0,index).reduce((a,b)=>a+Math.max(0,b),0)/total*Math.PI*2-Math.PI/2,end=start+Math.max(0,values[index])/total*Math.PI*2;if(end-start>=Math.PI*2-1e-10)return 'M 180 100 m -70 0 a 70 70 0 1 0 140 0 a 70 70 0 1 0 -140 0';return `M180,100 L${180+70*Math.cos(start)},${100+70*Math.sin(start)} A70,70 0 ${end-start>Math.PI?1:0},1 ${180+70*Math.cos(end)},${100+70*Math.sin(end)} Z`;}
 const colors=['#4472c4','#ed7d31','#a5a5a5','#ffc000','#70ad47','#5b9bd5'];
 function extent(data){const values=data.series.flatMap(s=>s.values),min=Math.min(0,...values),max=Math.max(0,...values);return {min,max:max===min?min+1:max};}
 const xPoint=(index,length)=>48+(length<=1?0:index/(length-1)*290);
 function yPoint(value,data){const {min,max}=extent(data);return 170-(value-min)/(max-min)*135;}
 function linePoints(series,data){return series.values.map((v,i)=>xPoint(i,series.values.length)+','+yPoint(v,data)).join(' ');}
 async function submitDialog(){
  let result;
  if(w.dialog==='find')result=await send('find',{query:dialogDraft});
  else if(w.dialog==='rename-sheet')result=await send('sheet.rename',{sheetId:sheet.id,name:dialogDraft});
  else if(w.dialog==='save-as'){await send('saveAs',{name:dialogDraft});return;}
  else if(w.dialog==='filter')result=await send('data.filter',{range:rangeDraft,column:Number(columnDraft),query:dialogDraft});
  else if(w.dialog==='sort')result=await send('data.sort',{range:rangeDraft,column:Number(columnDraft),descending:sortDescending,header:sortHeader});
  else if(w.dialog==='format')result=await send('range.format',{range:rangeDraft,format:{numberFormat:formatDraft}});
  else if(w.dialog==='chart')result=await send('chart.add',{type:chartType,range:rangeDraft,title:dialogDraft||'Chart'});
  else if(w.dialog==='paste')result=await send('range.paste',{range:rangeDraft,text:pasteDraft,delimiter:'comma'});
  if(result?.status==='applied')await send('dialog',{dialog:null});
 }
 onMount(()=>{const view=createMicrosoftOfficeNativeView({getRoot:()=>root,getState:()=>excelState,getProfile:()=>profile,windowId,appId:'excel',session:excelWindow,available:()=>available&&active,tick});const cleanup=registerView(windowId,view);return ()=>{view.destroy();if(typeof cleanup==='function')cleanup();};});
 const documentFonts=createDocumentFonts({getShared:name=>getShared(name),getFile:id=>getFile(id),getRoot:()=>root,getOwner:()=>[excelState,profile,window,windowId,w]});
</script>

<div bind:this={root} class:windows={cap.windows} class:classic={cap.classic} class:golden={cap.golden} class="office-shell excel" data-app="excel" data-profile={excelState.profileId} role="application" aria-label="Excel workbook"
 on:keydown={e=>{const suffix=({c:'copy',x:'cut',v:'paste'})[e.key.toLowerCase()];if(!w?.dialog&&(e.ctrlKey||e.metaKey)&&suffix){e.preventDefault();send(suffix);}}}
 on:copy={e=>{if(!w?.dialog){e.preventDefault();send('copy');}}} on:cut={e=>{if(!w?.dialog){e.preventDefault();send('cut');}}} on:paste={e=>{if(!w?.dialog){e.preventDefault();send('paste');}}}>
 {#if w}
 <header class="office-caption excel-caption"><div class="excel-quick"><button data-office-control="save" aria-label="Save workbook" on:click={()=>send('save')}>▣</button><button data-office-control="undo" aria-label="Undo" disabled={!w.history.undo.length} on:click={()=>send('undo')}>↶</button><button data-office-control="redo" aria-label="Redo" disabled={!w.history.redo.length} on:click={()=>send('redo')}>↷</button></div><strong>{w.document.title}{w.dirty?' •':''} — Excel</strong><input class="excel-caption-search" data-office-control="caption-search" aria-label="Search sheet" placeholder="Search Sheet" value={w.findQuery} on:change={e=>send('find',{query:e.currentTarget.value})}/></header>
 <nav class="office-ribbon-tabs" aria-label="Ribbon tabs">{#if cap.windows}<button data-office-control="file-tab" on:click={()=>send('dialog',{dialog:'file'})}>File</button>{/if}{#each EXCEL_TABS.filter(tab=>!['Chart Design','Format'].includes(tab)||w.selectedChartId) as tab}<button data-office-control={'tab-'+tab.replaceAll(' ','-')} class:selected={w.tab===tab} aria-pressed={w.tab===tab} on:click={()=>send('tab',{tab})}>{tab}</button>{/each}<button class="excel-share" data-office-control="share" on:click={()=>send('share')}>Share</button></nav>
 <div class="office-ribbon" aria-label={w.tab+' ribbon'}>
 {#if w.tab==='Home'}
 <div class="office-ribbon-group"><button data-office-control="paste" on:click={()=>send('paste')}>Paste</button><div><button data-office-control="cut" on:click={()=>send('cut')}>Cut</button><button data-office-control="copy" on:click={()=>send('copy')}>Copy</button></div><small>Clipboard</small></div>
 <div class="office-ribbon-group excel-font"><div><select data-office-control="font-family" aria-label="Font family" value={selectedFormat.fontFamily} on:change={e=>format({fontFamily:e.currentTarget.value})}>{#each documentFonts.choices(selectedFormat.fontFamily) as font}<option value={font} disabled={!documentFonts.has(font)}>{font}{!documentFonts.has(font)?' (unavailable)':''}</option>{/each}</select><input data-office-control="font-size" aria-label="Font size" type="number" min="6" max="96" value={selectedFormat.fontSize} on:change={e=>format({fontSize:Number(e.currentTarget.value)})}/></div><div><button data-office-control="bold" class:pressed={selectedFormat.bold} aria-pressed={selectedFormat.bold} on:click={()=>format({bold:!selectedFormat.bold})}><b>B</b></button><button data-office-control="italic" class:pressed={selectedFormat.italic} aria-pressed={selectedFormat.italic} on:click={()=>format({italic:!selectedFormat.italic})}><i>I</i></button><label title="Fill color">Fill <input data-office-control="fill-color" aria-label="Cell fill color" type="color" value={selectedFormat.fill} on:change={e=>format({fill:e.currentTarget.value})}/></label><label title="Font color">A <input data-office-control="font-color" aria-label="Font color" type="color" value={selectedFormat.color} on:change={e=>format({color:e.currentTarget.value})}/></label></div><small>Font</small></div>
 <div class="office-ribbon-group"><select data-office-control="number-format" aria-label="Number format" value={selectedFormat.numberFormat} on:change={e=>format({numberFormat:e.currentTarget.value})}>{#each ['General','0','0.00','#,##0.00','$#,##0.00','0%','0.00%','yyyy-mm-dd','@'] as f}<option value={f}>{f==='@'?'Text':f}</option>{/each}</select><button data-office-control="format-cells" on:click={()=>send('dialog',{dialog:'format'})}>Format Cells…</button><small>Number</small></div>
 <div class="office-ribbon-group"><button data-office-control="autosum" on:click={()=>send('cell.set',{address:w.selection.focus,input:selected.row>1?'=SUM('+columnName(selected.column)+'1:'+columnName(selected.column)+(selected.row-1)+')':'=SUM(0)'})}>Σ AutoSum</button><button data-office-control="fill-down" on:click={()=>send('range.fill',{range:selection,direction:'down'})}>Fill Down</button><button data-office-control="find" on:click={()=>send('dialog',{dialog:'find'})}>Find &amp; Select</button><small>Editing</small></div>
 {:else if w.tab==='Insert'}<div class="office-ribbon-group"><button data-office-control="new-sheet" on:click={()=>send('sheet.add')}>Insert Worksheet</button><small>Sheets</small></div><div class="office-ribbon-group excel-chart-buttons">{#each ['bar','line','pie'] as type}<button data-office-control={'insert-'+type} on:click={()=>{chartType=type;send('dialog',{dialog:'chart'});}}><span class="excel-chart-symbol">{type==='bar'?'▥':type==='line'?'⌁':'◕'}</span>{type[0].toUpperCase()+type.slice(1)} Chart</button>{/each}<small>Charts</small></div>
 {:else if w.tab==='Page Layout'}<div class="office-ribbon-group"><button data-office-control="page-preview" on:click={()=>send('dialog',{dialog:'page-setup'})}>Print Preview</button><button data-office-control="print" on:click={()=>send('print')}>Print…</button><small>Page Setup</small></div><div class="office-ribbon-group"><label><input data-office-control="layout-gridlines" type="checkbox" checked={w.view.gridlines} on:change={e=>send('view',{gridlines:e.currentTarget.checked})}/> View Gridlines</label><button data-office-control="export-pdf" on:click={()=>send('export',{format:'pdf'})}>Export PDF</button><small>Sheet Options</small></div>
 {:else if w.tab==='Formulas'}<div class="office-ribbon-group"><button data-office-control="formula-help" on:click={()=>send('dialog',{dialog:'help'})}>ƒx Insert Function…</button><small>Function Library</small></div><div class="office-ribbon-group"><button data-office-control="calculate" on:click={()=>send('calculate')}>Calculate Now</button><label><input data-office-control="show-formulas" type="checkbox" checked={w.view.formulas} on:change={e=>send('view',{formulas:e.currentTarget.checked})}/> Show Formulas</label><small>Formula Auditing</small></div>
 {:else if w.tab==='Data'}<div class="office-ribbon-group"><button data-office-control="sort-ascending" on:click={()=>send('data.sort',{range:selection,column:selectionBounds.minColumn,descending:false,header:false})}>A ↓ Z</button><button data-office-control="sort-descending" on:click={()=>send('data.sort',{range:selection,column:selectionBounds.minColumn,descending:true,header:false})}>Z ↓ A</button><button data-office-control="sort-dialog" on:click={()=>send('dialog',{dialog:'sort'})}>Sort…</button><small>Sort</small></div><div class="office-ribbon-group"><button data-office-control="filter" on:click={()=>send('dialog',{dialog:'filter'})}>Filter…</button><button data-office-control="clear-filters" on:click={()=>send('data.filter.clear')}>Clear</button><small>Filter</small></div><div class="office-ribbon-group"><button data-office-control="import-csv" on:click={()=>send('dialog',{dialog:'paste'})}>From CSV Text…</button><button data-office-control="export-csv" on:click={()=>send('export',{format:'csv'})}>Export CSV</button><small>Data</small></div>
 {:else if w.tab==='Review'}<div class="office-ribbon-group"><button data-office-control="review" on:click={()=>send('review')}>Check Workbook</button><button data-office-control="rename-sheet" on:click={()=>send('dialog',{dialog:'rename-sheet'})}>Rename Sheet…</button><small>Workbook</small></div><p class="excel-ribbon-note">Local workbook review reports actual formula errors.<br/>Cloud coauthoring and passwords are not simulated.</p>
 {:else if ['Chart Design','Format'].includes(w.tab)&&selectedChart}
 <div class="office-ribbon-group"><label>Chart type<select data-office-control="chart-type" value={selectedChart.type} on:change={e=>send('chart.update',{chartId:selectedChart.id,type:e.currentTarget.value})}><option value="bar">Column</option><option value="line">Line</option><option value="pie">Pie</option></select></label><small>Type</small></div>
 <div class="office-ribbon-group"><label>Source<input data-office-control="chart-source" aria-label="Chart source range" value={selectedChart.range} on:change={e=>send('chart.update',{chartId:selectedChart.id,range:e.currentTarget.value})}/></label><label>Title<input data-office-control="chart-title" aria-label="Chart title" value={selectedChart.title} on:change={e=>send('chart.update',{chartId:selectedChart.id,title:e.currentTarget.value})}/></label><small>Chart Elements</small></div>
 <div class="office-ribbon-group"><button data-office-control="delete-selected-chart" on:click={()=>send('chart.delete',{chartId:selectedChart.id})}>Delete Chart</button><small>Selection</small></div>
 {:else}<div class="office-ribbon-group"><label><input data-office-control="gridlines" type="checkbox" checked={w.view.gridlines} on:change={e=>send('view',{gridlines:e.currentTarget.checked})}/> Gridlines</label><label><input data-office-control="freeze" type="checkbox" checked={!!w.view.frozenRows} on:change={e=>send('view',{frozenRows:e.currentTarget.checked?1:0})}/> Freeze Top Row</label><small>Show</small></div>
 <div class="office-ribbon-group"><button data-office-control="zoom-100" on:click={()=>send('view',{zoom:1})}>100%</button><input data-office-control="zoom" aria-label="Zoom" type="range" min=".5" max="2" step=".1" value={w.view.zoom} on:input={e=>send('view',{zoom:Number(e.currentTarget.value)})}/><small>Zoom</small></div>
 <div class="office-ribbon-group"><label>Column width <input data-office-control="column-width" aria-label="Selected column width" type="number" min="24" max="600" value={sheet.columnWidths[columnName(selected.column)]??90} on:change={e=>send('column.width',{column:columnName(selected.column),width:Number(e.currentTarget.value)})}/></label><label>Row height <input data-office-control="row-height" aria-label="Selected row height" type="number" min="16" max="300" value={sheet.rowHeights[selected.row]??22} on:change={e=>send('row.height',{row:selected.row,height:Number(e.currentTarget.value)})}/></label><small>Cell Size</small></div>
 <div class="office-ribbon-group"><button data-office-control="new-window" on:click={()=>send('window.new')}>New Workbook</button><small>Window</small></div>{/if}
 </div>
 {#if operationError}<div class="excel-operation-error" role="alert">{operationError}</div>{/if}
 <div class="excel-formula-row"><input data-office-control="name-box" aria-label="Name box: cell or range" value={selection} on:change={e=>send('selection.set',{range:e.currentTarget.value.toUpperCase()})}/><span class="excel-fx">ƒx</span><input data-office-control="formula-bar" aria-label="Formula bar" value={selectedCell?.input??''} on:change={e=>send('cell.set',{address:w.selection.focus,input:e.currentTarget.value})}/></div>
 <main class="office-workspace excel-workspace">
 <div class="excel-grid-scroll" class:no-grid={!w.view.gridlines} style:font-size={11*w.view.zoom+'px'}>
 <table class="excel-grid" aria-label={sheet.name+' worksheet'}>
  <colgroup><col style="width:42px"/>{#each columns as c}<col style:width={(sheet.columnWidths[columnName(c)]??90)*w.view.zoom+'px'}/>{/each}</colgroup>
  <thead><tr><th class="excel-corner" aria-label="Row and column headings"></th>{#each columns as c}<th class:highlight={c>=selectionBounds.minColumn&&c<=selectionBounds.maxColumn}><button data-office-control={'column-'+columnName(c)} aria-label={'Select column '+columnName(c)} on:click={()=>send('selection.set',{range:columnName(c)+startRow+':'+columnName(c)+Math.min(1048576,startRow+69)})}>{columnName(c)}</button></th>{/each}</tr></thead>
  <tbody>{#each rows as r}
   <tr class:frozen={r<=w.view.frozenRows} style:top={r<=w.view.frozenRows?26+(r-1)*22+'px':undefined} style:height={(sheet.rowHeights[r]??22)*w.view.zoom+'px'}>
    <th class:highlight={r>=selectionBounds.minRow&&r<=selectionBounds.maxRow}><button data-office-control={'row-'+r} aria-label={'Select row '+r} on:click={()=>send('selection.set',{range:columnName(startColumn)+r+':'+columnName(Math.min(16384,startColumn+15))+r})}>{r}</button></th>
    {#each columns as c}
     {@const address=columnName(c)+r}{@const cell=sheet.cells[address]}{@const value=computed.sheets[sheet.id]?.[address]??{type:'blank',value:null}}
     <td class:selected={inSelection(r,c)} class:current={w.selection.focus===address} class:error={value.type==='error'} style:background={cell?.format.fill??'#ffffff'}>
      <input data-office-control={'cell-'+address} aria-label={address} title={cell?.input??''} class:numeric={value.type==='number'} style:font-family={documentFonts.css(cell?.format.fontFamily??'Calibri',cell?.format.bold,cell?.format.italic)} style:font-size={(cell?.format.fontSize??11)*w.view.zoom+'px'} style:font-weight={cell?.format.bold?'700':'400'} style:font-style={cell?.format.italic?'italic':'normal'} style:color={cell?.format.color??'#000000'} value={focusedCell===address||w.view.formulas?cell?.input??'':formatCellValue(value,cell?.format)}
       on:focus={e=>{focusedCell=address;if(w.selection.focus!==address)selectCell(address);e.currentTarget.value=cell?.input??'';}}
       on:mousedown={e=>{if(e.shiftKey){e.preventDefault();selectCell(address,true);}}}
       on:change={e=>{if(e.currentTarget.value!==(cell?.input??''))send('cell.set',{address,input:e.currentTarget.value});}}
       on:blur={()=>focusedCell=null} on:keydown={e=>navigate(e,address)}
      />
     </td>
    {/each}
   </tr>
  {/each}</tbody>
 </table>
 </div>
 {#if charts.length}<aside class="excel-charts" aria-label="Worksheet charts">{#each charts as chart}<section class="excel-chart" class:chosen={w.selectedChartId===chart.id}><header><button data-office-control={'chart-'+chart.id} on:click={()=>send('chart.select',{chartId:chart.id})}>{chart.title||'Chart'}</button><button data-office-control={'chart-delete-'+chart.id} aria-label={'Delete '+chart.title} on:click={()=>send('chart.delete',{chartId:chart.id})}>×</button></header><svg viewBox="0 0 390 215" role="img" aria-label={chart.title+' from '+chart.range}>
 {#if chart.type==='pie'}{#each chart.data.series[0]?.values??[] as value,i}<path d={piePath(chart.data.series[0].values,i)} fill={colors[i%colors.length]} stroke="white"><title>{chart.data.labels[i]}: {value}</title></path>{/each}
 {:else}<line x1="48" x2="350" y1={yPoint(0,chart.data)} y2={yPoint(0,chart.data)} stroke="#888"/>{#each chart.data.series as series,s}{#if chart.type==='line'}<polyline points={linePoints(series,chart.data)} fill="none" stroke={colors[s%colors.length]} stroke-width="2"/>{#each series.values as value,i}<circle cx={xPoint(i,series.values.length)} cy={yPoint(value,chart.data)} r="3" fill={colors[s%colors.length]}><title>{series.name} — {chart.data.labels[i]}: {value}</title></circle>{/each}{:else}{#each series.values as value,i}{@const bw=280/Math.max(1,series.values.length)/Math.max(1,chart.data.series.length)}<rect x={50+i*280/Math.max(1,series.values.length)+s*bw} y={Math.min(yPoint(0,chart.data),yPoint(value,chart.data))} width={Math.max(1,bw-3)} height={Math.abs(yPoint(value,chart.data)-yPoint(0,chart.data))} fill={colors[s%colors.length]}><title>{series.name} — {chart.data.labels[i]}: {value}</title></rect>{/each}{/if}{/each}{#each chart.data.labels as label,i}<text x={50+i*290/Math.max(1,chart.data.labels.length)} y="187" font-size="9">{label.length>12?label.slice(0,12)+'…':label}</text>{/each}<text x="4" y="37" font-size="9">{extent(chart.data).max}</text><text x="4" y="172" font-size="9">{extent(chart.data).min}</text>{/if}
 </svg><div class="excel-legend">{#each chart.type==='pie'?chart.data.labels:chart.data.series.map(s=>s.name) as label,i}<span><i style:background={colors[i%colors.length]}></i>{label}</span>{/each}</div><footer>{chart.range}{#if chart.data.errors.length}<strong> · {chart.data.errors.join('; ')}</strong>{/if}</footer></section>{/each}</aside>{/if}
 </main>
 <div class="excel-sheet-tabs"><span class="excel-sheet-nav">‹　›</span>{#each w.document.sheets as s}<button data-office-control={'sheet-'+s.id} class:selected={s.id===sheet.id} on:click={()=>send('sheet.select',{sheetId:s.id})} on:dblclick={()=>send('dialog',{dialog:'rename-sheet'})}>{s.name}</button>{/each}<button data-office-control="sheet-add" aria-label="Add worksheet" on:click={()=>send('sheet.add')}>＋</button><button class="excel-delete-sheet" data-office-control="sheet-delete" disabled={w.document.sheets.length===1} on:click={()=>send('sheet.delete',{sheetId:sheet.id})}>Delete Sheet</button></div>
 <footer class="office-statusbar"><span aria-live="polite">{documentFonts.error||w.status||'Ready'}{w.filters.length?' · Filter Mode':''}</span><span>{stats.length?'Average: '+Number((stats.reduce((a,b)=>a+b,0)/stats.length).toPrecision(8))+'   Count: '+stats.length+'   Sum: '+Number(stats.reduce((a,b)=>a+b,0).toPrecision(10)):''}</span><input data-office-control="status-zoom" aria-label="Worksheet zoom" type="range" min=".5" max="2" step=".1" value={w.view.zoom} on:input={e=>send('view',{zoom:Number(e.currentTarget.value)})}/><span>{Math.round(w.view.zoom*100)}%</span></footer>
 {#if w.dialog}<div class="office-dialog-backdrop"><section class="office-dialog excel-dialog" role="dialog" aria-modal="true" aria-label={w.dialog}><header><h2>{({'templates':'New Workbook','file':'File','find':'Find','rename-sheet':'Rename Sheet','save-as':'Save As','sort':'Sort','filter':'Filter','format':'Format Cells','chart':'Insert Chart','paste':'Import CSV Text','page-setup':'Print Preview','close':'Save changes?','help':'Formula Library','about':'About Microsoft Excel'})[w.dialog]??w.dialog}</h2><button data-office-control="dialog-close" aria-label="Close dialog" on:click={()=>send('dialog',{dialog:null})}>×</button></header>
 {#if operationError}<div class="excel-operation-error" role="alert">{operationError}</div>{/if}
 {#if w.dialog==='templates'}<div class="office-templates">{#each [['blank','Blank Workbook'],['budget','Monthly budget'],['sales','Quarterly sales']] as [template,label]}<button data-office-control={'template-'+template} on:click={()=>send('template',{template})}><span class="excel-template-preview">▦</span><strong>{label}</strong></button>{/each}</div>
 {:else if w.dialog==='file'}<div class="excel-file-actions">{#each [['New','window.new'],['Open…','open'],['Save','save'],['Print…','print']] as [label,suffix]}<button data-office-control={'file-'+suffix} on:click={()=>send(suffix)}>{label}</button>{/each}<button data-office-control="file-save-as" on:click={()=>send('dialog',{dialog:'save-as'})}>Save As…</button><button data-office-control="file-templates" on:click={()=>send('dialog',{dialog:'templates'})}>New from Template…</button></div>
 {:else if w.dialog==='help'}<p>Installed font families are the original shared Font Book/Font Library sources, not proprietary Apple or Microsoft fonts. Enablement and source changes update this mounted document. Unavailable authored family names remain literal and use a safe browser rendering fallback; existing export font-embedding scopes are unchanged.</p><p>Enter formulas beginning with <b>=</b>. Arithmetic + − * / ^ %, comparisons = &lt;&gt; &lt; &gt; &lt;= &gt;=, &amp; text concatenation, and parentheses are parsed locally.</p><p><b>SUM, AVERAGE, MIN, MAX, COUNT, IF</b> accept cells, ranges and comma- or semicolon-separated arguments. IF evaluates only its selected branch.</p><code>=IF(SUM(B2:B5)&gt;2000,"Over budget","Within budget")</code><p>Absolute references: $A$1, A$1, $A1. Cross-sheet: Sales!B2 or 'Monthly budget'!B2. Errors retain typed values: #DIV/0!, #REF!, #NAME?, #VALUE!, #NUM!, #CYCLE!.</p><p>XLSX files retain formulas and cell formats. CSV exports evaluated visible values from the active sheet, not formulas, charts or styles.</p>
 <label>Function source range<input data-office-control="function-range" bind:value={rangeDraft}/></label><p>Insert into selected cell {w.selection.focus}. Choose a source range that does not contain that cell to avoid a circular reference.</p><div class="excel-file-actions">{#each ['SUM','AVERAGE','MIN','MAX','COUNT'] as fn}<button data-office-control={'function-'+fn} on:click={async()=>{const result=await send('cell.set',{address:w.selection.focus,input:'='+fn+'('+rangeDraft+')'});if(result?.status==='applied')await send('dialog',{dialog:null});}}>{fn}</button>{/each}</div>
 {:else if w.dialog==='about'}<h3>{cap.version}</h3><p>{cap.disclosure}</p><p>Editable sparse cells, range formulas, sheet operations, sorting, filtering and linked charts. Genuine XLSX, CSV and PDF outputs.</p>
 {:else if w.dialog==='page-setup'}<p>PDF output uses the shared local print layout; worksheet text is rendered, with chart data disclosed rather than claiming Office print fidelity.</p><p>{w.document.title} · {sheet.name} · {Object.keys(sheet.cells).length} cells · {sheet.charts.length} charts</p><button data-office-control="preview-print" on:click={()=>send('print')}>Print…</button><button data-office-control="preview-export" on:click={()=>send('export',{format:'pdf'})}>Export PDF</button>
 {:else if w.dialog==='close'}<p>Save changes to {w.document.title} before closing?</p><button data-office-control="close-save" on:click={()=>send('save')}>Save</button><button data-office-control="close-discard" on:click={()=>send('window.close',{discard:true})}>Don't Save</button>
 {:else}<form on:submit|preventDefault={submitDialog}>
 {#if ['sort','filter','format','chart','paste'].includes(w.dialog)}<label>Range<input data-office-control="dialog-range" bind:value={rangeDraft}/></label>{/if}
 {#if ['find','rename-sheet','save-as','filter','chart'].includes(w.dialog)}<label>{w.dialog==='filter'?'Contains':w.dialog==='chart'?'Title':w.dialog==='save-as'?'File name':'Text'}<input data-office-control="dialog-text" bind:value={dialogDraft}/></label>{/if}
 {#if ['sort','filter'].includes(w.dialog)}<label>Column number<input data-office-control="dialog-column" type="number" min="1" max="16384" bind:value={columnDraft}/></label>{/if}
 {#if w.dialog==='sort'}<label><input data-office-control="sort-header" type="checkbox" bind:checked={sortHeader}/> My range has headers</label><label><input data-office-control="sort-descending-option" type="checkbox" bind:checked={sortDescending}/> Descending</label>{/if}
 {#if w.dialog==='format'}<label>Number format<input data-office-control="dialog-number-format" bind:value={formatDraft}/></label><p>Examples: General, 0.00, $#,##0.00, 0%, yyyy-mm-dd.</p>{/if}
 {#if w.dialog==='chart'}<label>Chart type<select data-office-control="dialog-chart-type" bind:value={chartType}><option value="bar">Column</option><option value="line">Line</option><option value="pie">Pie</option></select></label><p>First text row supplies series names; first text column supplies category labels. Pie uses the first numeric series.</p>{/if}
 {#if w.dialog==='paste'}<label>CSV data<textarea data-office-control="dialog-csv" rows="7" bind:value={pasteDraft}></textarea></label><p>Quoted commas and multiline fields are supported. Pasted formulas are evaluated; never paste untrusted formulas unintentionally.</p>{/if}
 <footer><button type="button" data-office-control="dialog-cancel" on:click={()=>send('dialog',{dialog:null})}>Cancel</button><button data-office-control="dialog-apply" class="primary" type="submit">{w.dialog==='save-as'?'Save':'Apply'}</button></footer></form>{/if}
 </section></div>{/if}
 {/if}
</div>
